export const getUploadBackupUrl = () => {
  return `/api/backups/upload`;
};

/**
 * Administrators only. Stores a backup file that was downloaded earlier, from this or another installation, so it appears in the list and can be restored. Nothing is restored by this call. The listed date is the moment the backup was taken, not the upload. Send the file as multipart/form-data.
 * @summary Add a downloaded backup to the server
 */
export const uploadBackup = async (
  uploadBackupRequest: UploadBackupRequest,
  options?: Parameters<typeof customFetch>[1],
): Promise<BackupResponse> => {
  const formData = new FormData();
  if (uploadBackupRequest.file !== undefined) {
    formData.append(`file`, uploadBackupRequest.file);
  }
  if (uploadBackupRequest.note !== undefined && uploadBackupRequest.note !== null) {
    formData.append(`note`, uploadBackupRequest.note);
  }

  return customFetch<BackupResponse>(getUploadBackupUrl(), {
    ...options,
    method: "POST",
    body: formData,
  });
};

